-- tools/clog2top_equiv_tb.vhd -- TRACK CLOG2TOP, 2026-08-29.
--
-- ARE THE FOUR LOCALLY-DECLARED `clog2` BODIES THIS PROJECT CARRIES THE SAME
-- FUNCTION AS `work.util_pkg.clog2`, AND DID CHANGING THEM CHANGE ANYTHING?
--
-- Editing a function that sizes ports on the strength of "it looks like the
-- same recipe" is exactly the failure mode this project's record is full of.
-- Every body below is therefore checked against TWO independent oracles, not
-- against each other:
--
--   * GOLD_R, generated by Python's `(n-1).bit_length()` -- a closed form,
--     no loop, no VHDL, arbitrary precision.  Regenerate with the snippet in
--     `docs/debugging/2026-08-29_clog2top-shadowed-clog2.md`.
--   * `clog2_shift`, a 64-bit shift oracle in this file, for the sweeps that
--     are too large to tabulate.  Neither doubles a `natural` nor halves one.
--
-- A DIFFERENTIAL TEST AGAINST THE THING BEING REPLACED IS BLIND WHEREVER THAT
-- THING WAS ALREADY WRONG.  Two of the old bodies below abort above 2**30 and
-- one aborts at 0, which is precisely where the edits matter, so old-vs-new
-- alone would have proved nothing there.  The old bodies are called ONLY on
-- their own domains; above and below those the oracles are the only witnesses.
--
-- NOT A GATE ROW.  `sim/regress.sh` discovers rows by globbing `tb_*.vhd` in
-- `sim/` and `tb/` ONLY (`regress.sh:924`, over SUITE_DIRS), and builds its
-- analysis closure from `rtl/`, `sim/`, `sim/micro/` and `tb/` (`regress.sh:850`).
-- `tools/` is in neither list, so this adds no row and does not move
-- BASELINE_PASS.  Run it by hand:
--
--   W=$(mktemp -d)
--   ghdl -a --std=08 --workdir=$W rtl/util_pkg.vhd tools/clog2top_equiv_tb.vhd
--   ghdl -r --std=08 --workdir=$W clog2top_equiv_tb
--
-- GHDL here is the mcode backend: `ghdl -e` produces no binary and silently
-- succeeds, so the run above is `-a` then `-r` and never `-e`.
--
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use ieee.math_real.all;
use work.util_pkg.clog2;

entity clog2top_equiv_tb is end entity;

architecture tb of clog2top_equiv_tb is

  -- ---- A: the body DELETED from `architecture rtl of llama_top` ----------
  -- Verbatim as it stood at 5a19f984, renamed only so both can be named in
  -- one scope.  It hid `use work.util_pkg.clog2;` for the whole architecture.
  -- ABORTS above 2**30: `2**v` needs 2**31 at n = 2**30 + 1.
  function clog2_top_old(n : natural) return natural is
    variable v : natural := 0;
  begin
    while (2**v) < n loop v := v + 1; end loop;
    return v;
  end function;

  -- ---- B: `rtl/hbm_tg.vhd`, before and after -----------------------------
  -- The old body ABORTS AT n = 0: `variable v : natural := n - 1` is a bound
  -- check failure on the declaration itself.  Defined on 1 .. natural'high.
  function clog2_tg_old(n : natural) return natural is
    variable r : natural := 0; variable v : natural := n - 1;
  begin
    while v > 0 loop r := r + 1; v := v / 2; end loop; return r;
  end function;

  function clog2_tg_new(n : natural) return natural is
    variable r : natural := 0; variable v : natural;
  begin
    if n <= 1 then return 0; end if;
    v := n - 1;
    while v > 0 loop r := r + 1; v := v / 2; end loop; return r;
  end function;

  -- ---- C: the three `sim/micro` copies, before and after -----------------
  -- All three carried byte-identical bodies.  `positive`, so no zero case;
  -- ABORTS above 2**30 for the same reason as A.
  function clog2_micro_old(n : positive) return natural is
    variable r : natural := 0; variable v : positive := 1;
  begin
    while v < n loop v := v * 2; r := r + 1; end loop; return r;
  end function;

  function clog2_micro_new(n : positive) return natural is
    variable r : natural := 0; variable v : natural;
  begin
    if n <= 1 then return 0; end if;
    v := n - 1;
    while v > 0 loop r := r + 1; v := v / 2; end loop; return r;
  end function;

  -- ---- the shift oracle: independent of every loop above -----------------
  -- No `2**v`, no halving.  Doubles a 64-bit unsigned by shifting, so nothing
  -- can leave the type at any argument in `natural`.
  function clog2_shift(n : natural) return natural is
    variable p  : unsigned(63 downto 0) := to_unsigned(1, 64);
    variable nn : unsigned(63 downto 0);
  begin
    if n <= 1 then return 0; end if;
    nn := to_unsigned(n, 64);
    for r in 1 to 63 loop
      p := shift_left(p, 1);
      if p >= nn then return r; end if;
    end loop;
    return 64;
  end function;

  -- The largest argument the two doubling bodies are DEFINED on.  MEASURED,
  -- phase L below: at 2**30 + 1 they need 2**31 and abort elaboration.
  constant DBL_MAX : natural := 2**30;

