begin
  main : process is
    variable np, ns, g : natural;
    variable bad : natural := 0;
    variable seed1 : positive := 20260829;
    variable seed2 : positive := 7;
    variable rr : real;
    variable n  : natural;

    -- One value, every body that is DEFINED on it, against the given oracle
    -- answer.  `dbl` and `zer` say which bodies may legally be called.
    procedure chk(nv : natural; want : natural; tag : string) is
      variable v : natural;
    begin
      v := clog2(nv);
      if v /= want then bad := bad + 1;
        report tag & " pkg n=" & integer'image(nv) & " got=" & integer'image(v)
             & " want=" & integer'image(want) severity error; end if;
      v := clog2_shift(nv);
      if v /= want then bad := bad + 1;
        report tag & " shift n=" & integer'image(nv) & " got=" & integer'image(v)
             & " want=" & integer'image(want) severity error; end if;
      v := clog2_tg_new(nv);
      if v /= want then bad := bad + 1;
        report tag & " tg_new n=" & integer'image(nv) & " got=" & integer'image(v)
             & " want=" & integer'image(want) severity error; end if;
      if nv >= 1 then
        v := clog2_tg_old(nv);
        if v /= want then bad := bad + 1;
          report tag & " tg_old n=" & integer'image(nv) & " got="
               & integer'image(v) & " want=" & integer'image(want)
               severity error; end if;
        v := clog2_micro_new(nv);
        if v /= want then bad := bad + 1;
          report tag & " micro_new n=" & integer'image(nv) & " got="
               & integer'image(v) & " want=" & integer'image(want)
               severity error; end if;
      end if;
      if nv <= DBL_MAX then
        v := clog2_top_old(nv);
        if v /= want then bad := bad + 1;
          report tag & " top_old n=" & integer'image(nv) & " got="
               & integer'image(v) & " want=" & integer'image(want)
               severity error; end if;
        if nv >= 1 then
          v := clog2_micro_old(nv);
          if v /= want then bad := bad + 1;
            report tag & " micro_old n=" & integer'image(nv) & " got="
                 & integer'image(v) & " want=" & integer'image(want)
                 severity error; end if;
        end if;
      end if;
    end procedure;
  begin
    -- ---- phase G: the Python golden table -------------------------------
    -- The only phase whose expected answers were produced OUTSIDE VHDL.
    -- It carries every 2**k +/- 1 boundary and every argument llama_top,
    -- hbm_tg and the micro lanes actually form at the real 9B config.
    for i in GOLD_N'range loop
      chk(GOLD_N(i), GOLD_R(i), "GOLD");
    end loop;
    report "GOLD  " & integer'image(GOLD_N'length)
         & " Python-generated values, 7 bodies vs an out-of-VHDL oracle, ok";

    -- ---- phase E: exhaustive 0 .. 2**21 ---------------------------------
    for i in 0 to 2**21 loop
      chk(i, clog2_shift(i), "EXH");
    end loop;
    report "EXH   exhaustive 0..2**21 ok, " & integer'image(2**21 + 1)
         & " values, every body defined there";

    -- ---- phase Z: the zero and one cases, stated one by one --------------
    -- `clog2_tg_old(0)` is NOT called: it is a bound check failure on its own
    -- variable declaration.  MEASURED standalone at `-gAXI_DW=4`:
    --   ghdl-mcode:error: bound check failure at rtl/hbm_tg.vhd:197
    -- That is the whole reason hbm_tg changed.
    report "ZERO  n=0 -> pkg=" & integer'image(clog2(0))
         & " shift=" & integer'image(clog2_shift(0))
         & " tg_new=" & integer'image(clog2_tg_new(0))
         & " top_old=" & integer'image(clog2_top_old(0))
         & "  (tg_old(0): bound check failure -- NOT CALLED)";
    report "ONE   n=1 -> pkg=" & integer'image(clog2(1))
         & " tg_old=" & integer'image(clog2_tg_old(1))
         & " tg_new=" & integer'image(clog2_tg_new(1))
         & " micro_old=" & integer'image(clog2_micro_old(1))
         & " micro_new=" & integer'image(clog2_micro_new(1));

    -- ---- phase L: the doubling bodies' ceiling ---------------------------
    report "DBL   2**30      = " & integer'image(DBL_MAX)
         & " -> top_old=" & integer'image(clog2_top_old(DBL_MAX))
         & " micro_old=" & integer'image(clog2_micro_old(DBL_MAX))
         & " pkg=" & integer'image(clog2(DBL_MAX))
         & "  (last value the doubling bodies survive)";
    report "DBL   2**30+1    = " & integer'image(DBL_MAX + 1)
         & " -> pkg=" & integer'image(clog2(DBL_MAX + 1))
         & " oracle=" & integer'image(clog2_shift(DBL_MAX + 1))
         & " tg_new=" & integer'image(clog2_tg_new(DBL_MAX + 1))
         & "  (top_old/micro_old: overflow -- NOT CALLED)";
    report "DBL   natural'high = " & integer'image(natural'high)
         & " -> pkg=" & integer'image(clog2(natural'high))
         & " oracle=" & integer'image(clog2_shift(natural'high))
         & " tg_new=" & integer'image(clog2_tg_new(natural'high));

    -- ---- phase R: random over the whole of natural -----------------------
    for i in 1 to 2**20 loop
      uniform(seed1, seed2, rr);
      n := natural(rr * 2147483646.0);
      np := clog2(n);
      ns := clog2_shift(n);
      if np /= ns then bad := bad + 1;
        report "RND oracle mismatch n=" & integer'image(n) severity error;
      end if;
      if clog2_tg_new(n) /= ns then bad := bad + 1;
        report "RND tg_new mismatch n=" & integer'image(n) severity error;
      end if;
      if n <= DBL_MAX and clog2_top_old(n) /= ns then bad := bad + 1;
        report "RND top_old mismatch n=" & integer'image(n) severity error;
      end if;
      if n >= 1 and n <= DBL_MAX and clog2_micro_old(n) /= ns then
        bad := bad + 1;
        report "RND micro_old mismatch n=" & integer'image(n) severity error;
      end if;
      if n >= 1 and clog2_micro_new(n) /= ns then bad := bad + 1;
        report "RND micro_new mismatch n=" & integer'image(n) severity error;
      end if;
    end loop;
    report "RND   1048576 draws over 0..natural'high-1 ok";

    if bad = 0 then
      report "CLOG2TOP EQUIV: PASS" severity note;
    else
      report "CLOG2TOP EQUIV: FAIL  " & integer'image(bad) & " mismatches"
        severity failure;
    end if;
    wait;
  end process;
end architecture;
